CREATE TABLE CORS_Station (
    CORS_Station_Description VARCHAR(255),
    CORS_Station_ID INTEGER PRIMARY KEY,
    CORS_Station_Name VARCHAR(255)
);

CREATE TABLE CORS_Network (
    CORS_Network_Description VARCHAR(255),
    CORS_Network_ID INTEGER PRIMARY KEY,
    CORS_Network_Name VARCHAR(255)
);

CREATE TABLE Station_Network_Relationship (
    CORS_Network_ID INTEGER NOT NULL,
    CORS_Station_ID INTEGER NOT NULL,
    Effective_End_Time DATETIME,
    Effective_Start_Time DATETIME,
    PRIMARY KEY (CORS_Station_ID, CORS_Network_ID, Effective_Start_Time, Effective_End_Time),
    FOREIGN KEY (CORS_Network_ID) REFERENCES CORS_Network(CORS_Network_ID),
    FOREIGN KEY (CORS_Station_ID) REFERENCES CORS_Station(CORS_Station_ID)
);
